buildGradleAdditions.insert:
tasks.named('preBuild').configure {
    doFirst {
        def manifest = new XmlSlurper(false, false).parse(file('src/main/AndroidManifest.xml'))
        def useAppFiles = manifest.application.'meta-data'.find {
            it.'@android:name'.text() == 'com.epicgames.unreal.GameActivity.bUseExternalFilesDir'
        }
        if (useAppFiles.'@android:value'.text() != 'true') {
            throw new GradleException('UGP requires app-specific files storage. Package with UAT and bUseExternalFilesDir=True.')
        }
        // UAT keeps the cooked OBB for staging and publication. The APK
        // only needs its bootstrap assets and the game libraries.
        delete fileTree('src/main/assets') { include '*.obb.png' }
    }
}
